import React, { useState } from 'react';

const MemberManagementTab = () => {
  // 가상의 회원 목록 (실제로는 백엔드에서 가져올 데이터)
  const [members, setMembers] = useState([
    { id: 1, nickname: '도몬', email: 'domon@example.com', status: '정상', registeredDate: '2024-01-01' },
    { id: 2, nickname: '여행가Lv1', email: 'traveler1@example.com', status: '정지', registeredDate: '2024-02-10' },
    { id: 3, nickname: '사찰지킴이', email: 'templefan@example.com', status: '정상', registeredDate: '2024-03-20' },
    { id: 4, nickname: '탈퇴예정', email: 'withdrawal@example.com', status: '탈퇴', registeredDate: '2024-04-05' },
  ]);

  const handleMemberAction = (memberId, actionType) => {
    // 실제 백엔드 API 호출 로직
    const member = members.find(m => m.id === memberId);
    if (!member) return;

    if (actionType === '정지') {
      alert(`${member.nickname} 님을 정지 처리합니다. (API 연동 필요)`);
      setMembers(members.map(m => m.id === memberId ? { ...m, status: '정지' } : m));
    } else if (actionType === '탈퇴') {
      if (window.confirm(`${member.nickname} 님을 정말 탈퇴 처리하시겠습니까?`)) {
        alert(`${member.nickname} 님을 탈퇴 처리합니다. (API 연동 필요)`);
        setMembers(members.map(m => m.id === memberId ? { ...m, status: '탈퇴' } : m));
      }
    } else if (actionType === '상세보기') {
      alert(`${member.nickname} 님의 상세 정보를 봅니다. (별도 페이지/모달 구현 필요)`);
      console.log('상세보기:', member);
    }
  };

  return (
    <div className="tab-content-section member-management-tab">
      <h3 className="tab-content-title">회원 관리 🧑‍🤝‍🧑</h3>
      <div className="search-form">
        <input type="text" placeholder="회원 닉네임 또는 이메일 검색" />
        <button className="search-button">검색</button>
      </div>

      <table className="admin-member-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>닉네임</th>
            <th>이메일</th>
            <th>가입일</th>
            <th>상태</th>
            <th>액션</th>
          </tr>
        </thead>
        <tbody>
          {members.map(member => (
            <tr key={member.id}>
              <td>{member.id}</td>
              <td>{member.nickname}</td>
              <td>{member.email}</td>
              <td>{member.registeredDate}</td>
              <td>
                <span className={member.status === '정상' ? 'member-status-active' : 'member-status-inactive'}>
                  {member.status}
                </span>
              </td>
              <td className="member-actions">
                <button className="action-button" onClick={() => handleMemberAction(member.id, '상세보기')}>상세보기</button>
                {member.status !== '정지' && member.status !== '탈퇴' && (
                  <button className="action-button delete-button" onClick={() => handleMemberAction(member.id, '정지')}>정지</button>
                )}
                {member.status !== '탈퇴' && (
                  <button className="action-button delete-button" onClick={() => handleMemberAction(member.id, '탈퇴')}>탈퇴</button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default MemberManagementTab;
